<script setup lang="ts">
import { confirmAction } from "../../confirmation";
import { Link, router, useForm, usePage } from '@inertiajs/vue3'; import MainLayout from '../../Layouts/MainLayout.vue'; import { ref } from 'vue';
defineProps<{items:Array<{id:number;tahun:string;semester:string;status:string;kelas_count:number}>}>(); const showForm=ref(false); const page=usePage(); const form=useForm({tahun:'',semester:'ganjil'}); const submit=()=>form.post('/master/tahun-pelajaran',{onSuccess:()=>{showForm.value=false;form.reset()}}); const activate=(id:number)=>router.patch(`/master/tahun-pelajaran/${id}/aktifkan`); const remove=async(id:number)=>{if(await confirmAction('Periode yang belum memiliki kelas ini akan dihapus.')) router.delete(`/master/tahun-pelajaran/${id}`)};
</script>
<template><MainLayout><main class="p-4 sm:p-6 lg:p-8"><div class="mx-auto max-w-7xl"><div v-if="page.props.flash?.success" class="mb-5 rounded-lg bg-emerald-50 px-4 py-3 text-sm font-medium text-emerald-700">{{ page.props.flash.success }}</div><div v-if="page.props.flash?.error" class="mb-5 rounded-lg bg-rose-50 px-4 py-3 text-sm font-medium text-rose-700">{{ page.props.flash.error }}</div><div class="mb-6 flex flex-wrap items-center justify-between gap-4"><div><div class="flex items-center gap-2 text-sm text-slate-500"><span>Master data</span><span>/</span><span class="font-medium text-indigo-600">Tahun pelajaran</span></div><h1 class="mt-2 text-2xl font-bold tracking-tight text-slate-900">Tahun pelajaran</h1><p class="mt-1 text-sm text-slate-500">Atur periode akademik yang aktif untuk operasional sekolah.</p></div><button class="sneat-primary rounded-lg px-4 py-2.5 text-sm font-semibold text-white" @click="showForm=!showForm">{{ showForm?'Tutup form':'＋ Tambah periode' }}</button></div><Transition name="soft-panel"><section v-if="showForm" class="sneat-card mb-6 p-5"><div class="mb-4"><h2 class="font-bold text-slate-900">Tambah tahun pelajaran</h2><p class="mt-1 text-xs text-slate-500">Format tahun: 2026/2027</p></div><form class="grid gap-4 sm:grid-cols-[1fr_1fr_auto] sm:items-end" @submit.prevent="submit"><div><label class="mb-2 block text-xs font-semibold uppercase text-slate-500">Tahun</label><input v-model="form.tahun" placeholder="2026/2027" class="w-full px-3 py-2.5" required><p v-if="form.errors.tahun" class="mt-1 text-xs text-rose-600">{{ form.errors.tahun }}</p></div><div><label class="mb-2 block text-xs font-semibold uppercase text-slate-500">Semester</label><select v-model="form.semester" class="w-full px-3 py-2.5"><option value="ganjil">Ganjil</option><option value="genap">Genap</option></select></div><button :aria-busy="form.processing" :disabled="form.processing" class="sneat-primary rounded-lg px-5 py-2.5 text-sm font-semibold text-white">{{ form.processing?'Menyimpan…':'Simpan' }}</button></form></section></Transition><section class="sneat-card overflow-hidden"><div class="flex items-center justify-between border-b border-slate-100 px-5 py-4 sm:px-6"><div><h2 class="font-bold text-slate-900">Daftar periode</h2><p class="mt-1 text-xs text-slate-500">{{ items.length }} periode terdaftar</p></div><span class="rounded-lg bg-indigo-50 px-3 py-1.5 text-xs font-semibold text-indigo-600">Periode akademik</span></div><div class="overflow-x-auto"><table class="sneat-table w-full text-left text-sm"><thead class="text-xs uppercase"><tr><th class="px-6 py-3">Tahun</th><th class="px-6 py-3">Semester</th><th class="px-6 py-3">Status</th><th class="px-6 py-3">Kelas</th><th class="px-6 py-3 text-right">Aksi</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in items" :key="item.id"><td class="px-6 py-4 font-semibold text-slate-800">{{ item.tahun }}</td><td class="px-6 py-4 capitalize text-slate-500">{{ item.semester }}</td><td class="px-6 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="item.status==='aktif'?'bg-emerald-50 text-emerald-700':'bg-slate-100 text-slate-600'">{{ item.status==='aktif'?'Aktif':'Nonaktif' }}</span></td><td class="px-6 py-4 text-slate-500">{{ item.kelas_count }} kelas</td><td class="space-x-2 px-6 py-4 text-right"><button v-if="item.status!=='aktif'" class="rounded-lg bg-indigo-50 px-3 py-2 text-xs font-semibold text-indigo-600 hover:bg-indigo-100" @click="activate(item.id)">Aktifkan</button><button v-if="item.kelas_count===0" class="rounded-lg bg-rose-50 px-3 py-2 text-xs font-semibold text-rose-600 hover:bg-rose-100" @click="remove(item.id)">Hapus</button><span v-if="item.status==='aktif'" class="text-xs text-slate-400">Periode aktif</span></td></tr><tr v-if="!items.length"><td colspan="5" class="px-6 py-14 text-center"><p class="text-sm font-medium text-slate-500">Belum ada tahun pelajaran</p><p class="mt-1 text-xs text-slate-400">Tambahkan periode pertama untuk mulai mengatur kelas.</p></td></tr></tbody></table></div></section></div></main></MainLayout></template>
